body.body:
// Valid empty result — NOT an error
{ "isError": false,
  "content": [{ "type": "text", "text": "No customer found matching that email. Query ran successfully, no matches." }],
  "resultCount": 0 }

// Access failure — IS an error
{ "isError": true,
  "content": [{ "type": "text", "text": "Could not reach customer database" }],
  "errorCategory": "transient", "isRetryable": true,
  "description": "Connection timed out after 5s. The query did not execute." }

// Grep — contents
Grep: "processLegacyOrder"            // files that CALL the function
Grep: "import.*from 'utils/auth'"     // files that import a module

// Glob — paths
Glob: "**/*.test.tsx"                  // all test files
Glob: "content/domains/**/*.mdx"       // MDX files in a directory
